(function(){const G=window.__game; const sp=JSON.parse(JSON.stringify(G.WK.PRESETS[2])); sp.start='luna'; G.WkF.begin(sp); G.WkF.hint=0; G.WkF.msgs.length=0;
 const m=G.WkF.main, sim=m.sim, B=sim.B; const qe=G.qfromAxes3([0,0,-1],[-1,0,0],[0,1,0]); const low=sim.lowest(qe,[0,1,0]); const a=0*Math.PI/180; const rr=B.R+0.03-low;
 const r=[rr*Math.sin(a),rr*Math.cos(a),0]; G.WK.use(B); const pj=G.WK.proj(r); const A=pj.qL,Bq=qe; const q=[A[3]*Bq[0]+A[0]*Bq[3]+A[1]*Bq[2]-A[2]*Bq[1],A[3]*Bq[1]-A[0]*Bq[2]+A[1]*Bq[3]+A[2]*Bq[0],A[3]*Bq[2]+A[0]*Bq[1]-A[1]*Bq[0]+A[2]*Bq[3],A[3]*Bq[3]-A[0]*Bq[0]-A[1]*Bq[1]-A[2]*Bq[2]];
 sim.setState(r,[0,0,0],q,[0,0,0]); sim.ctl.sas='stab'; sim.ctl.gear=1; sim.ctl.brake=1; G.WkF.snap=true; return {B:B.id,low}})()

